"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import { useState } from "react";

import { cn } from "@/lib/utils";

/** One reaction in the row. `label` names it for screen readers, for example "Thumbs up". */
export interface Reaction {
  id: string;
  emoji: string;
  label: string;
  count: number;
  reacted?: boolean;
}

/** Props for a row of reactions. The row holds its own counts after the first render. */
export interface ReactionsProps {
  reactions: Reaction[];
  onToggle?: (id: string, reacted: boolean) => void;
  /** Names the row, for example "Reactions to this comment". */
  "aria-label": string;
  className?: string;
}

const COUNT: Transition = { type: "spring", stiffness: 520, damping: 46, mass: 1 };
const POP: Transition = { duration: 0.32, ease: [0.23, 1, 0.32, 1] };
const INSTANT: Transition = { duration: 0 };

// 1 rolls the new count up from below, -1 rolls it down from above. The value
// travels through AnimatePresence's `custom`, because a leaving element keeps
// the props of its last render and would otherwise exit the old way.
type Direction = 1 | -1;
const ROLL = {
  enter: (dir: Direction) => ({ y: dir * 10, opacity: 0 }),
  shown: { y: 0, opacity: 1 },
  leave: (dir: Direction) => ({ y: -dir * 10, opacity: 0 }),
};

/**
 * A row of reaction toggles. Adding one pops the emoji and rolls the count up;
 * removing one rolls the count down and leaves the emoji still.
 */
export function Reactions({ reactions, onToggle, "aria-label": ariaLabel, className }: ReactionsProps) {
  const [items, setItems] = useState<(Reaction & { dir?: Direction })[]>(reactions);
  const reduceMotion = useReducedMotion();

  const toggle = (id: string) => {
    const target = items.find((item) => item.id === id);
    if (!target) return;
    const reacted = !target.reacted;
    setItems((current) =>
      current.map((item) =>
        item.id === id ? { ...item, reacted, dir: reacted ? 1 : -1, count: item.count + (reacted ? 1 : -1) } : item,
      ),
    );
    onToggle?.(id, reacted);
  };

  return (
    <div role="group" aria-label={ariaLabel} className={cn("flex flex-wrap gap-2", className)}>
      {items.map((item) => (
        <button
          key={item.id}
          type="button"
          aria-pressed={Boolean(item.reacted)}
          aria-label={`${item.label}, ${item.count}`}
          onClick={() => toggle(item.id)}
          className={cn(
            "inline-flex min-h-11 cursor-pointer touch-manipulation items-center gap-1.5 rounded-full border px-3 text-sm outline-none sm:min-h-9",
            "motion-safe:transition motion-safe:duration-150 active:scale-95",
            "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
            item.reacted
              ? "border-foreground/25 bg-accent text-foreground"
              : "border-border bg-background text-muted-foreground hover:bg-muted",
          )}
        >
          <motion.span
            aria-hidden="true"
            initial={false}
            animate={item.reacted && !reduceMotion ? { scale: [1, 1.35, 1] } : { scale: 1 }}
            transition={reduceMotion ? INSTANT : POP}
            className="inline-block text-base leading-none"
          >
            {item.emoji}
          </motion.span>
          <span aria-hidden="true" className="relative inline-flex overflow-hidden tabular-nums">
            <AnimatePresence
              mode="popLayout"
              initial={false}
              custom={item.dir ?? 1}
            >
              <motion.span
                key={item.count}
                custom={item.dir ?? 1}
                variants={ROLL}
                initial="enter"
                animate="shown"
                exit="leave"
                transition={reduceMotion ? INSTANT : COUNT}
                className="inline-block"
              >
                {item.count}
              </motion.span>
            </AnimatePresence>
          </span>
        </button>
      ))}
    </div>
  );
}
